const css=`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700&family=Playfair+Display:ital,wght@0,600;0,700;1,600&display=swap');:root{--ink:#402914;--cream:#fffdf8;--red:#87300c;--blue:#4d93c3;--line:#e7c067}*{box-sizing:border-box}body{margin:0;color:var(--ink);font:15px 'DM Sans',Arial;background:#fffdf8}.wrap{max-width:1080px;margin:auto;padding:0 25px}.top{height:72px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);line-height:1}.brand-mark{display:inline-grid;place-items:center;width:42px;height:42px;background:linear-gradient(180deg,#75aad5 0 32%,#fff 32% 68%,#75aad5 68%);border-radius:50%;border:1px solid #4d93c3;box-shadow:0 2px 0 #e7c067}.brand-mark i{font-style:normal;font-size:18px;color:#ffc449;text-shadow:0 1px 0 #87300c}.brand strong{display:block;font-size:13px;letter-spacing:.08em}.brand small{display:block;font-size:9px;letter-spacing:.18em;color:#87300c;margin-top:4px;font-weight:800}nav{display:flex;gap:24px}nav a{text-decoration:none;font-size:13px;color:var(--ink);font-weight:700;padding:8px 0;border-bottom:2px solid transparent}nav a:hover{color:var(--red);border-color:var(--red)}.hero{background:var(--cream);padding:72px 0}.eyebrow{color:var(--red);letter-spacing:.12em;font-size:10px;font-weight:700}.hero h1,h1,h2,h3{font-family:'Playfair Display';letter-spacing:-.04em}.hero h1,h1{font-size:clamp(43px,7vw,74px);line-height:.96;margin:16px 0}.hero em{color:var(--red)}.lead{max-width:630px;color:#5e5a52;font-size:18px;line-height:1.55}.button{display:inline-block;background:var(--blue);color:white;padding:14px 18px;text-decoration:none;margin-top:18px}.section{padding:65px 0}.grid{display:grid;grid-template-columns:2fr 1fr;gap:11px}.grid img{width:100%;height:430px;object-fit:cover}.grid aside img{height:209px;display:block;margin-bottom:11px}.facts{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:32px 0}.facts div{padding:18px;border-right:1px solid var(--line)}.facts div:last-child{border:0}.facts small{display:block;font-size:10px;color:#82796e;letter-spacing:.1em}.facts b{display:block;margin-top:8px}.body{display:grid;grid-template-columns:1fr 280px;gap:65px}.text{font-size:16px;line-height:1.7;color:#554d43}.text h2{font-size:34px;color:var(--ink)}.box{background:#e8f4fb;border-left:4px solid var(--blue);padding:18px 20px;margin:27px 0}.side{border-top:4px solid var(--red);padding-top:14px}.side p{line-height:1.5;color:#5e5a52}.card{border:1px solid var(--line);max-width:410px;text-decoration:none;display:block}.card img{width:100%;height:220px;object-fit:cover}.card div{padding:18px}.card h2{font-size:30px;margin:8px 0}.blog{background:var(--blue);color:#fff;padding:65px 0}.blog h1{color:#fff}.post{border-bottom:1px solid var(--line);padding:25px 0;max-width:760px}.post h2{font-size:30px;margin:8px 0}.post p{color:#5e5a52;line-height:1.5}footer{background:#402914;color:#fff;padding:42px 0 28px;margin-top:40px;font-size:13px;border-top:5px solid #ffc449}.footer-grid{display:grid;grid-template-columns:1.35fr .8fr .85fr;gap:35px}.footer-brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#fff;line-height:1}.footer-brand .brand-mark{box-shadow:none}.footer-brand strong{display:block;font-size:13px;letter-spacing:.08em}.footer-brand small{display:block;font-size:9px;letter-spacing:.18em;color:#ffc449;margin-top:4px;font-weight:800}.footer-intro p{max-width:390px;color:#f5e9d9;line-height:1.55;margin:16px 0 0}.footer-links{display:flex;flex-direction:column;gap:9px}.footer-links p,.footer-note p{font-size:10px;letter-spacing:.12em;color:#ffc449;font-weight:900;margin:3px 0 4px}.footer-links a{color:#fff;text-decoration:none;font-weight:700}.footer-links a:hover{color:#ffc449}.footer-note{display:flex;flex-direction:column;gap:12px}.footer-note span{color:#f5e9d9;line-height:1.45}.footer-note small{color:#b9d7ea;font-size:11px;margin-top:auto}@media(max-width:650px){.wrap{padding:0 20px}.top{height:66px}.brand-mark{width:36px;height:36px}.brand strong{font-size:11px}.brand small{font-size:8px}.top nav{gap:11px}.top nav a{font-size:12px}nav{gap:12px}.footer-grid{grid-template-columns:1fr;gap:25px}.footer-note{border-top:1px solid rgba(255,255,255,.18);padding-top:18px}.hero{padding:50px 0}.grid,.body{grid-template-columns:1fr}.grid img{height:280px}.grid aside{display:grid;grid-template-columns:1fr 1fr;gap:10px}.grid aside img{height:135px;margin:0}.facts{grid-template-columns:1fr 1fr}.facts div:nth-child(2){border-right:0}.facts div:nth-child(-n+2){border-bottom:1px solid var(--line)}}`;
function shell(title,body){return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><meta name="description" content="Restaurantes argentinos en Valencia, cultura y guías."><style>${css}</style></head><body><header class="top wrap"><a class="brand" href="/" aria-label="Comida Argentina en Valencia, inicio"><span class="brand-mark" aria-hidden="true"><i>☀</i></span><span><strong>COMIDA ARGENTINA</strong><small>EN VALENCIA</small></span></a><nav><a href="/restaurantes">Restaurantes</a><a href="/guias">Guías</a><a href="/blog">Blog</a></nav></header>${body}<footer><div class="wrap footer-grid"><div class="footer-intro"><a class="footer-brand" href="/" aria-label="Comida Argentina en Valencia, inicio"><span class="brand-mark" aria-hidden="true"><i>☀</i></span><span><strong>COMIDA ARGENTINA</strong><small>EN VALENCIA</small></span></a><p>Una guía editorial para encontrar sabores argentinos, descubrir Valencia y sentirse un poco más cerca de casa</p></div><div class="footer-links"><p>EXPLORÁ LA WEB</p><a href="/restaurantes">Restaurantes argentinos</a><a href="/guias">Guías de Valencia</a><a href="/blog">Blog y cultura</a></div><div class="footer-note"><p>HECHO PARA LA COMUNIDAD</p><span>Comer, recorrer y entender Argentina desde Valencia</span><small>© 2026 Comida Argentina en Valencia</small></div></div></footer></body></html>`}
function mila(){return shell('Mila Restaurante Argentino en Valencia | Carta, precio y reseña',`<main><section class="hero"><div class="wrap"><p class="eyebrow">RESTAURANTE ARGENTINO · L'EIXAMPLE</p><h1>Mila<br><em>Restaurante</em></h1><p class="lead">Una propuesta argentina contemporánea en Conde de Altea: milanesas, empanadas, fainá y platos para compartir, en una sala cuidada y con terraza.</p><a class="button" href="https://www.milarestaurante.es/reservar/" target="_blank" rel="noopener">Reservar mesa →</a><div class="facts"><div><small>ZONA</small><b>L'Eixample</b></div><div><small>PRECIO MEDIO</small><b>25 €</b></div><div><small>IDEAL PARA</small><b>Cita o amigos</b></div><div><small>RESERVA</small><b>Recomendada</b></div></div></div></section><section class="section wrap"><div class="grid"><img src="${photo}" alt="Fachada de Mila Restaurante en Valencia"><aside><img src="${photo}" alt="Comida argentina en Mila"><img src="${photo}" alt="Restaurante Mila en L'Eixample"></aside></div></section><section class="section wrap body"><article class="text"><p class="eyebrow">LA RESEÑA</p><h2>Argentina con una vuelta contemporánea</h2><p>Mila se aleja de la parrilla clásica para trabajar una carta argentina más amplia y actual: empanadas, milanesas, fainá y entrantes pensados para compartir. Está en Calle Conde de Altea, 39, una zona muy cómoda para una cena en L'Eixample.</p><div class="box"><b>¿Para qué ir?</b><p>Para una cena informal cuidada, una cita o una salida con amigos cuando querés comida argentina pero también un ambiente agradable y una carta con opciones más creativas.</p></div><h2>Qué pedir</h2><p>Las empanadas de ternera, espinaca, caprese o pollo son una buena entrada. También destacan las croquetas de asado y el choribao. Si querés salir de lo habitual, el fainá con burrata, jamón serrano y pistacho, o el gofre de patata con mollejas laqueadas y mayonesa de chimichurri, muestran el costado más personal de la propuesta.</p><h2>Antes de reservar</h2><p>El ticket medio publicado es de 25 €. Conviene reservar para cenas de fin de semana y planes de grupo. La propuesta ofrece alternativas vegetarianas, veganas y sin gluten según los directorios de reserva; al reservar, confirmá las necesidades específicas con el local.</p><h2>Datos contrastados</h2><p>TheFork sitúa el precio medio en 25 € y registra una valoración de 9/10 basada en más de 1.700 opiniones; el servicio y el ambiente aparecen entre los aspectos mejor puntuados. La carta oficial confirma las especialidades y precios indicados.</p><h2>Preguntas frecuentes</h2><p><b>¿Dónde está Mila Restaurante?</b><br>En Calle Conde de Altea, 39, 46005 València.</p><p><b>¿Cuánto cuesta comer en Mila?</b><br>El precio medio publicado es de 25 € por persona.</p><p><b>¿Qué tipo de comida sirve?</b><br>Cocina argentina contemporánea, con milanesas, empanadas, fainá y entrantes para compartir.</p></article><aside class="side"><h3>Información práctica</h3><p><b>Dirección</b><br>Calle Conde de Altea, 39<br>46005 València</p><p><b>Teléfono</b><br>+34 747 855 578</p><p><b>Web</b><br><a href="https://www.milarestaurante.es/" target="_blank" rel="noopener">milarestaurante.es</a></p><p><b>Última verificación</b><br>Agosto de 2026</p><a class="button" href="https://share.google/q2mCXeKu338qnUvbO" target="_blank" rel="noopener">Ver en Google Maps →</a></aside></section></main>`)}
