export default {async fetch(request){const p=new URL(request.url).pathname;const record=restaurantRecords.find(r=>p===`/restaurantes/${r.slug}`);const article=articles.find(a=>p===`/blog/${a.slug}`);const pages={'/':homeEnhanced,'/restaurantes':restaurants,'/restaurantes/mila':milaVisual,'/guias':guides,'/blog':blog};const render=record?()=>restaurantDetail(record):article?()=>articlePage(article):(pages[p]||homeEnhanced);return new Response(render(),{headers:{'content-type':'text/html;charset=utf-8'}})}};
